import test from 'node:test';
import assert from 'node:assert/strict';
import {mkdtempSync,writeFileSync,rmSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
import {execFileSync} from 'node:child_process';
import {hash} from './manifest.mjs';
import {installationFixture} from './staging-install-test-fixture.mjs';
import {createInstallGrant} from './ci-install-grant.mjs';
import {validateRepairDelta,validateDeadlineRepairDelta} from './repair-recovery.mjs';
import {validateDeadlineRepairBytes,validateDeadlineFocusedTerminal,deadlineRecoveryCertificate,validateDeadlineGrantEvidence,DEADLINE_PATH,DEADLINE_BEFORE,DEADLINE_AFTER,DEADLINE_RECOVERY_POLICY} from './deadline-recovery-policy.mjs';
const original=()=>Buffer.from('// original fixture\n'+'// preserved assertion and native guard\n'.repeat(40)+DEADLINE_BEFORE+"\n it('unchanged case',async()=>{ await actualOwner(); expect(true).toBe(true); });\n});\n");
function deltaInput(){const before=original();return {changed:[DEADLINE_PATH],before,after:Buffer.from(before.toString().replace(DEADLINE_BEFORE,DEADLINE_AFTER))};}
test('v4 accepts only the exact bounded fixture deadline insertion',()=>{const f=deltaInput(),d=validateDeadlineRepairBytes(f);assert.equal(d.timeoutMs,60000);assert.equal(d.path,DEADLINE_PATH);assert.notEqual(d.beforeSha256,d.afterSha256);});
for(const [name,change] of [
 ['application path',f=>f.changed=['core/read.ts']],['extra file',f=>f.changed.push('test/other.test.ts')],['empty source',f=>f.before=Buffer.alloc(0)],['text instead of bytes',f=>f.before=f.before.toString()],['assertion mutation',f=>f.after=Buffer.from(f.after.toString().replace('toBe(true)','toBe(false)'))],['case name mutation',f=>f.after=Buffer.from(f.after.toString().replace('unchanged case','changed case'))],['fixture mutation',f=>f.after=Buffer.from(f.after.toString().replace('actualOwner()','fakeOwner()'))],['larger deadline',f=>f.after=Buffer.from(f.after.toString().replace('60_000','120_000'))],['extra comment',f=>f.after=Buffer.concat([f.after,Buffer.from('// extra')])],['missing original marker',f=>f.before=Buffer.from(f.before.toString().replace(DEADLINE_BEFORE,'different'))],['repeated original marker',f=>f.before=Buffer.concat([f.before,Buffer.from(DEADLINE_BEFORE)])],['invalid UTF8',f=>f.before=Buffer.concat([f.before,Buffer.from([255])])]
])test('v4 deadline bytes refuse '+name,()=>{const f=deltaInput();change(f);assert.throws(()=>validateDeadlineRepairBytes(f));});
function certificateInput(){const f=installationFixture(),controller='e'.repeat(40),deadline=validateDeadlineRepairBytes(deltaInput());const c={kind:'AUTHENTICATED_CROSS_SOURCE_RECOVERY',recoveryPolicy:'aihr-cross-source-recovery/v2',policyVersion:f.evidence.policyVersion,sha:f.evidence.sha,controller:f.evidence.controller,verificationController:controller,reviewedController:controller,pendingReview:false,releaseAuthorized:false,baseline:f.evidence.baseline,runId:f.run.id,originalRunId:100,originalSha:'c'.repeat(40),originalConclusion:'failure',verificationDiagnostic:{controller,runId:900},compilers:[{runId:200}],focusedSources:[{runId:200}],units:[{kind:'repaired-source'}],disposition:{fresh:['db-example']},tests:5,suiteFiles:2,browserFiles:0};const recovery=deadlineRecoveryCertificate(c,deadline);recovery.delta={changed:[DEADLINE_PATH],deadline};const evidence={...f.evidence,...recovery,recovery,fingerprint:hash(recovery)};return {...f,evidence};}
test('v4 retains the original failure while granting only the new successful source-bound build',()=>{const f=certificateInput();assert.equal(createInstallGrant(f).runId,123);assert.equal(f.evidence.recovery.originalConclusion,'failure');assert.equal(f.evidence.recovery.recoveryPolicy,DEADLINE_RECOVERY_POLICY);});
for(const [name,change] of [
 ['pending review',f=>f.evidence.recovery.pendingReview=true],['wrong reviewer controller',f=>f.evidence.recovery.reviewedController='f'.repeat(40)],['wrong delta path',f=>f.evidence.recovery.delta.changed=['core/read.ts']],['altered deadline',f=>f.evidence.recovery.deadline.timeoutMs=120000],['missing byte hash',f=>delete f.evidence.recovery.deadline.beforeSha256],['different public source identity',f=>f.evidence.sha='f'.repeat(40)],['relabelled original success',f=>f.evidence.recovery.originalConclusion='success'],['missing original source',f=>f.evidence.recovery.originalSha=f.evidence.recovery.sha],['missing full-process replacement',f=>f.evidence.recovery.units=[]],['failed new build',f=>f.run.conclusion='failure'],['rerun build',f=>f.run.run_attempt=2],['missing diagnostic',f=>delete f.evidence.recovery.verificationDiagnostic],['missing compiler',f=>f.evidence.recovery.compilers=[]]
])test('v4 deadline grant refuses '+name,()=>{const f=certificateInput();change(f);f.evidence.fingerprint=hash(f.evidence.recovery);assert.throws(()=>createInstallGrant(f));});
test('v4 cannot wrap missing verification or broaden replacement coverage',()=>{const f=certificateInput(),c={...f.evidence.recovery,kind:'AUTHENTICATED_CROSS_SOURCE_RECOVERY',recoveryPolicy:'aihr-cross-source-recovery/v2'};assert.throws(()=>deadlineRecoveryCertificate({...c,disposition:{fresh:['one','two']}},c.deadline));assert.throws(()=>deadlineRecoveryCertificate({...c,originalConclusion:'success'},c.deadline));});
test('actual immutable Git delta is exact; v2 product admission remains closed to test repair',()=>{
 const root=mkdtempSync(join(tmpdir(),'deadline-delta-')),git=(...args)=>execFileSync('git',args,{cwd:root,encoding:'utf8'}).trim();
 try{git('init','-q');git('config','user.name','fixture');git('config','user.email','fixture@example.test');execFileSync('mkdir',['-p',join(root,'test')]);writeFileSync(join(root,DEADLINE_PATH),original());git('add','.');git('commit','-qm','before');const originalSha=git('rev-parse','HEAD');writeFileSync(join(root,DEADLINE_PATH),deltaInput().after);git('add','.');git('commit','-qm','deadline');const candidate=git('rev-parse','HEAD');assert.equal(validateDeadlineRepairDelta({cwd:root,original:originalSha,candidate}).deadline.timeoutMs,60000);assert.throws(()=>validateRepairDelta({cwd:root,original:originalSha,candidate}));writeFileSync(join(root,'test/other.test.ts'),'other');git('add','.');git('commit','-qm','extra');assert.throws(()=>validateDeadlineRepairDelta({cwd:root,original:originalSha,candidate:git('rev-parse','HEAD')}));}finally{rmSync(root,{recursive:true,force:true});}
});

function terminal(){const t=n=>new Date(1700000000000+n*1000).toISOString();return [{report:{groups:{NODB:[],DB:[DEADLINE_PATH]},startedAt:t(1),batches:[{startedAt:t(2),endedAt:t(3)}],databaseTerminalEvidence:{capturedAt:t(4)},endedAt:t(5)},producer:{completed_at:t(6)}}];}
test('v4 DB capture is terminal after the entire process',()=>assert.doesNotThrow(()=>validateDeadlineFocusedTerminal(terminal())));
for(const [name,change] of [['during process',f=>f[0].report.databaseTerminalEvidence.capturedAt=f[0].report.batches[0].startedAt],['missing batch completion',f=>delete f[0].report.batches[0].endedAt],['after report',f=>f[0].report.databaseTerminalEvidence.capturedAt=f[0].producer.completed_at],['missing evidence',f=>delete f[0].report.databaseTerminalEvidence],['extra process',f=>f.push(f[0])],['mixed process',f=>f[0].report.groups.NODB=[DEADLINE_PATH]]])test('v4 terminal capture refuses '+name,()=>{const f=terminal();change(f);assert.throws(()=>validateDeadlineFocusedTerminal(f));});
